/* Insects & Arthropods set additions — cards appended after insects.js.
   (insects.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'insects.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('insects');
  if (!S) return;
  var extra = [{"name":"Alfalfa Leafcutter Bee","rarity":"uncommon","id":"alfalfa-leafcutter-bee","subtitle":"Bee","details":"This small leafcutter bee lines its nest cells with neat circles cut from leaves, and it is raised commercially to pollinate alfalfa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ARS%20Megachile%20rotundata.jpg?width=1024"},{"name":"Squash Bee","rarity":"uncommon","id":"squash-bee","subtitle":"Bee","details":"Squash bees specialize almost entirely on squash and pumpkin flowers, and males often sleep inside the closed blossoms overnight and each morning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peponapis%20pruinosa%2C%20f%2C%20back%2C%20Centre%20Co.%2C%20PA%202017-03-09-14.09%20%2834015857766%29.jpg?width=1024"},{"name":"Sweat Bee","rarity":"uncommon","id":"sweat-bee","subtitle":"Bee","details":"Small metallic or striped sweat bees are common flower visitors across North America and nest in burrows in bare soil in gardens and open ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Halictus%20ligatus%20F%20%2813632631963%29.jpg?width=1024"},{"name":"Cuckoo Wasp","rarity":"uncommon","id":"cuckoo-wasp","subtitle":"Wasp","details":"Cuckoo wasps glitter in metallic red and green, and lay their eggs in the nests of other wasps and bees they parasitize.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysis%20ignita%2C%20Gemeine%20Goldwespe%20April%202020.jpg?width=1024"},{"name":"Cicada Killer Wasp","rarity":"uncommon","id":"cicada-killer-wasp","subtitle":"Wasp","details":"Among the largest wasps in eastern North America, females hunt cicadas and provision underground burrows for their young.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cicada%20Killer%20Wasp%20%28Crabroninae%2C%20Sphecius%20speciosus%29%20%2829241735262%29.jpg?width=1024"},{"name":"Pharaoh Ant","rarity":"uncommon","id":"pharaoh-ant","subtitle":"Ant","details":"Pharaoh ant colonies have many queens and readily split into new nests, a strategy called budding that spreads the colony.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hormiga%20fara%C3%B3n%20%28Monomorium%20pharaonis%29%2C%20Hartelholz%2C%20M%C3%BAnich%2C%20Alemania%2C%202020-06-21%2C%20DD%2001-19%20FS.jpg?width=1024"},{"name":"Odorous House Ant","rarity":"uncommon","id":"odorous-house-ant","subtitle":"Ant","details":"These small ants move their flexible colonies frequently, nesting under stones, mulch, and bark throughout the season as conditions change.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Odorous%20House%20Ants%20-%20Tapinoma%20sessile%20and%20Aphids%2C%20Merrimac%20Farm%20Wildlife%20Management%20Area%2C%20Aden%2C%20Virginia%2C%20September%2022%2C%202015%20%2853511901666%29.jpg?width=1024"},{"name":"Black Garden Ant","rarity":"uncommon","id":"black-garden-ant","subtitle":"Ant","details":"Black garden ants farm aphids for honeydew and stage dramatic summer mating flights when winged queens and males emerge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20garden%20ant%20%28Lasius%20niger%29%20and%20green%20peach%20aphids%20%28Myzus%20persicae%29%20on%20a%20branch%2C%20Jardim%20da%20Funda%C3%A7%C3%A3o%20Calouste%20Gulbenkian%2C%20Lisbon%2C%20Portugal%20julesvernex2.jpg?width=1024"},{"name":"Mining Bee","rarity":"uncommon","id":"mining-bee","subtitle":"Bee","details":"Mining bees are solitary ground nesters that appear in early spring, each female digging her own burrow and pollen stores.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Andrena%20carlini%2C%20f%2C%20back%2C%20Cecil%20Co.%20Maryland%202016-03-29-14.03.jpg?width=1024"},{"name":"Mason Wasp","rarity":"uncommon","id":"mason-wasp","subtitle":"Wasp","details":"Mason wasps reuse old burrows and cavities, sealing nest cells with mud and stocking them with caterpillars for their young.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ancistrocerus%20antilope.jpg?width=1024"},{"name":"Wood Ant","rarity":"uncommon","id":"wood-ant","subtitle":"Ant","details":"Wood ants build large thatched mound nests from pine needles and twigs, and spray formic acid to defend the colony and the mound nest itself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Formica%20rufa%20sideview.jpg?width=1024"},{"name":"Violet Dropwing","rarity":"uncommon","id":"violet-dropwing","subtitle":"Dragonfly","details":"Males of this African and Mediterranean species turn a vivid violet-purple, perching in a drooped-wing pose over warm water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trithemis%20annulata%2C%20Greece.jpg?width=1024"},{"name":"Broad Scarlet","rarity":"uncommon","id":"broad-scarlet","subtitle":"Dragonfly","details":"Male broad scarlets are intense scarlet red all over, and the species has been expanding northward across Europe in recent decades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Broad%20scarlet%20%28Crocothemis%20erythraea%29%20male%20Cyprus.jpg?width=1024"},{"name":"Four-spotted Chaser","rarity":"uncommon","id":"four-spotted-chaser","subtitle":"Dragonfly","details":"A sturdy dragonfly with a dark spot on each wing's leading edge, it is one of the first species active at northern ponds in spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Four-spotted%20Chaser%20%28Libellula%20quadrimaculata%29.JPG?width=1024"},{"name":"Eastern Amberwing","rarity":"uncommon","id":"eastern-amberwing","subtitle":"Dragonfly","details":"Among the smallest North American dragonflies, the amberwing's golden wings may mimic a wasp as it flutters over pond edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/233%20365%20-%20Eastern%20Amberwing%20-%20Perithemis%20tenera%2C%20Woodbridge%2C%20Virginia%2C%20August%2020%2C%202023%20%2853130979196%29.jpg?width=1024"},{"name":"Familiar Bluet","rarity":"uncommon","id":"familiar-bluet","subtitle":"Damselfly","details":"Familiar bluets are slender blue damselflies common at almost any still water, often the most abundant bluet at a pond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Enallagma%20civile-mating.jpg?width=1024"},{"name":"Blue-tailed Damselfly","rarity":"uncommon","id":"blue-tailed-damselfly","subtitle":"Damselfly","details":"This widespread European damselfly is mostly dark with a bright blue tail-light segment near the tip of the abdomen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue-tailed%20Damselfies%20%28Ischnura%20elegans%29%20two%20males%20and%20female%20%28typica%29.jpg?width=1024"},{"name":"Large Red Damselfly","rarity":"uncommon","id":"large-red-damselfly","subtitle":"Damselfly","details":"One of the first damselflies to emerge in spring in Europe, the large red damselfly favors ponds, ditches, and slow streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Large%20Red%20damselfly%20%28Pyrrhosoma%20nymphula%29%20male.jpg?width=1024"},{"name":"Autumn Meadowhawk","rarity":"uncommon","id":"autumn-meadowhawk","subtitle":"Dragonfly","details":"Autumn meadowhawks fly late into the season, often the last dragonflies active at northern ponds on mild fall days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Autumn%20Meadowhawk%20%28Sympetrum%20vicinum%29%20%2822654537846%29.jpg?width=1024"},{"name":"Yellow Garden Spider","rarity":"uncommon","id":"yellow-garden-spider","subtitle":"Spider","details":"A large black and yellow orb weaver of North America, females spanning 7 cm, that writes a bold zigzag stabilimentum through its web's centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argiope%20aurantia%2C%202022-08-14%2C%20Beechview%2C%2001.jpg?width=1024"},{"name":"Banded Garden Spider","rarity":"uncommon","id":"banded-garden-spider","subtitle":"Spider","details":"A silvery orb weaver with dark-banded legs found on several continents; females span about 25 mm and spin webs low in shrubs and tall grass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argiope%20July%202012-2.jpg?width=1024"},{"name":"Marbled Orb Weaver","rarity":"uncommon","id":"marbled-orb-weaver","subtitle":"Spider","details":"An orange and brown marbled orb weaver about 18 mm long, common in North American woods; it hides in a silk retreat beside its web by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marbled%20Orb%20Weaver.jpg?width=800"},{"name":"Orchard Orb Weaver","rarity":"uncommon","id":"orchard-orb-weaver","subtitle":"Spider","details":"A slender green and silver spider about 7 mm long that spins a tilted orb web in shrubs and orchards across the eastern Americas in warm months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leucage%20venusta%2007%2020x%20%2842168875384%29.jpg?width=1024"},{"name":"Goldenrod Crab Spider","rarity":"uncommon","id":"goldenrod-crab-spider","subtitle":"Spider","details":"A flower-hunting spider about 10 mm long that can slowly change colour between white and yellow to match petals while it waits to ambush bees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Misumena%20vatia%20male.jpg?width=1024"},{"name":"Zebra Jumping Spider","rarity":"uncommon","id":"zebra-jumping-spider","subtitle":"Spider","details":"A small black and white striped jumper, only about 6 mm long, that hunts on sunny walls and fences in Europe and North America by sight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kaldari%20Salticus%20scenicus%20female%2001.jpg?width=1024"},{"name":"Tan Jumping Spider","rarity":"uncommon","id":"tan-jumping-spider","subtitle":"Spider","details":"A flattened grey-brown jumping spider about 13 mm long, camouflaged for tree bark and walls in North America, where it stalks flies and moths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male%20Platycryptus%20undatus%20-%2053735590928.jpg?width=1024"},{"name":"Southern House Spider","rarity":"uncommon","id":"southern-house-spider","subtitle":"Spider","details":"Females of this southern spider are dark and span up to 5 cm, living for years in a funnel web in wall crevices; males are tan and wander widely.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kukulcania.jpg?width=1024"},{"name":"Long-bodied Cellar Spider","rarity":"uncommon","id":"long-bodied-cellar-spider","subtitle":"Spider","details":"A pale spider with a tiny body and legs up to 5 cm long that hangs upside down in a loose web in cellars and corners, vibrating when disturbed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pholcus-phalangioides-20190725b.jpg?width=1024"},{"name":"Nursery Web Spider","rarity":"uncommon","id":"nursery-web-spider","subtitle":"Spider","details":"A tan North American hunter about 19 mm long; the female carries her egg sac in her jaws, then builds a silk nursery tent for the spiderlings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nursery%20Web%20Spider%20%2828728058700%29.jpg?width=1024"},{"name":"Six-spotted Fishing Spider","rarity":"uncommon","id":"six-spotted-fishing-spider","subtitle":"Spider","details":"A pond-side spider spanning up to 9 cm that walks on water, rows with its legs and senses ripples from insects trapped on the surface film.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolomedes%20triton%20129329911.jpg?width=1024"},{"name":"Elongated Long-jawed Orb Weaver","rarity":"uncommon","id":"elongated-long-jawed-orb-weaver","subtitle":"Spider","details":"A very slender spider about 30 mm with legs, stretched along streamside stems in North America; it builds a small horizontal orb over water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long-jawed%20Orbweaver%20-%20Tetragnatha%20elongata%2C%20Lake%20Kerr%2C%20Henderson%2C%20North%20Carolina.jpg?width=1024"},{"name":"Eastern Parson Spider","rarity":"uncommon","id":"eastern-parson-spider","subtitle":"Spider","details":"A dark ground spider about 13 mm long with a white stripe down its abdomen like a cravat; it hunts at night and hides in a silk retreat by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/EasternParsonSpider.jpg?width=1024"},{"name":"Red-femured Spotted Orb Weaver","rarity":"uncommon","id":"red-femured-spotted-orb-weaver","subtitle":"Spider","details":"A mottled brown orb weaver of the southeastern United States, about 16 mm long, that spins a fresh web near lights and eaves almost every night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neoscona%20domiciliorum%20-%202021.jpg?width=1024"},{"name":"Florida Bark Scorpion","rarity":"uncommon","id":"florida-bark-scorpion","subtitle":"Scorpion","details":"A slender dark scorpion about 10 cm long found in Florida and the Caribbean, often under bark and in wood piles, glowing under ultraviolet light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centruroides%20gracilis.jpg?width=1024"},{"name":"Dune Scorpion","rarity":"uncommon","id":"dune-scorpion","subtitle":"Scorpion","details":"A pale sand-coloured scorpion about 9 cm long from dunes of the American Southwest, well camouflaged as it burrows and hunts insects at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Smeringurus%20mesaensis.jpg?width=1024"},{"name":"Arizona Devil Scorpion","rarity":"uncommon","id":"arizona-devil-scorpion","subtitle":"Scorpion","details":"A yellow-brown scorpion of Arizona and nearby deserts, about 8 cm long, with striped tail segments; it shelters under rocks and debris by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paravaejovis%20spinigerus.jpg?width=1024"},{"name":"Sawfinger Scorpion","rarity":"uncommon","id":"sawfinger-scorpion","subtitle":"Scorpion","details":"A small pale scorpion about 5 cm long from the Baja California region, named for the serrated edge on its movable pincer finger, hunting at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Serradigitus%20gertschi%20Ueda.jpg?width=1024"},{"name":"Dog-day Cicada","rarity":"uncommon","id":"dog-day-cicada","subtitle":"Cicada","details":"Named for the dog days of summer, this cicada's high, whining song rises and falls from treetops in the hottest weeks of the year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dog-day%20Cicada%20%28Neotibicen%20canicularis%29%20-%20Guelph%2C%20Ontario.jpg?width=800"},{"name":"Swamp Cicada","rarity":"uncommon","id":"swamp-cicada","subtitle":"Cicada","details":"The swamp cicada sings a rattling, pulsating call from riverside trees and is among the earliest cicadas calling each morning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neotibicen%20tibicen%20406145053.jpg?width=1024"},{"name":"Green-striped Grasshopper","rarity":"uncommon","id":"green-striped-grasshopper","subtitle":"Grasshopper","details":"This early-season grasshopper flashes yellow hindwings in flight and is one of the first grasshoppers to mature each spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chortophaga%20viridifasciata%20425021183.jpg?width=1024"},{"name":"Two-striped Grasshopper","rarity":"uncommon","id":"two-striped-grasshopper","subtitle":"Grasshopper","details":"Two pale stripes run down its back, and this grasshopper ranges widely across North American grasslands, gardens, and roadsides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melanoplus%20bivittatus%3B%20Two-striped%20Grasshopper%203.jpg?width=1024"},{"name":"Migratory Grasshopper","rarity":"uncommon","id":"migratory-grasshopper","subtitle":"Grasshopper","details":"A strong flier with clear wings and red hind legs, the migratory grasshopper ranges from grasslands to mountain meadows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melanoplus%20sanguinipes-female.jpg?width=1024"},{"name":"Snowy Tree Cricket","rarity":"uncommon","id":"snowy-tree-cricket","subtitle":"Cricket","details":"The snowy tree cricket chirps faster as nights warm, so closely tracking temperature that its rate can be used to estimate it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oecanthus%20fultoni%20-%202024-09-01.jpg?width=1024"},{"name":"Fall Field Cricket","rarity":"uncommon","id":"fall-field-cricket","subtitle":"Cricket","details":"Fall field crickets mature in late summer, and their chirping becomes one of the signature sounds of autumn evenings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fall%20Field%20Cricket%20%28Gryllus%20pennsylvanicus%29%20-%20Algonquin%20Provincial%20Park%202019-09-24.jpg?width=1024"},{"name":"Japanese Burrowing Cricket","rarity":"uncommon","id":"japanese-burrowing-cricket","subtitle":"Cricket","details":"Introduced from Asia, this dark burrowing cricket now chirps from lawns and gardens across the southeastern United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Velarifictorus%20micado-paralyzed%20dorsal.jpg?width=1024"},{"name":"Fork-tailed Bush Katydid","rarity":"uncommon","id":"fork-tailed-bush-katydid","subtitle":"Katydid","details":"Males of this green katydid end in a distinctive forked tail plate, and the species sings short, sharp notes from shrubs at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fork-tailed%20Bush%20Katydid%2C%20Scudderia%20furcata%20-%20Flickr%20-%20GregTheBusker.jpg?width=1024"},{"name":"Oblong-winged Katydid","rarity":"uncommon","id":"oblong-winged-katydid","subtitle":"Katydid","details":"A broad-winged, leaf-green katydid of meadows and forest edges, it occasionally appears in an unexpected pink color form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amblycorypha%20oblongifolia%2C-face%202012-07-26-17.04.13-ZS-PMax.jpg?width=1024"},{"name":"Vietnamese Stick Insect","rarity":"uncommon","id":"vietnamese-stick-insect","subtitle":"Stick Insect","details":"This slender stick insect from Vietnam reproduces almost entirely without males and is widely kept for its twig-like camouflage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Annam-Stabschrecke%20Medauroidea%20extradentata%201.jpg?width=1024"},{"name":"Southern Two-striped Walkingstick","rarity":"uncommon","id":"southern-two-striped-walkingstick","subtitle":"Stick Insect","details":"Pairs of this walkingstick wander together for days, the smaller male riding on the female's back through southern pinelands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anisomorpha%20buprestoides.jpg?width=1024"},{"name":"Wheel Bug","rarity":"uncommon","id":"wheel-bug","subtitle":"Bug","details":"The wheel bug carries a cog-like crest of teeth on its thorax, unique among North American bugs, and hunts caterpillars slowly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Wheel%20bug%20%28Arilus%20cristatus%29%20eating%20a%20Japanese%20beetle%20%28Popillia%20japonica%29.jpg?width=1024"},{"name":"Large Milkweed Bug","rarity":"uncommon","id":"large-milkweed-bug","subtitle":"Bug","details":"Orange and black large milkweed bugs feed in groups on milkweed seeds and migrate seasonally across eastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asclepias%20syriaca-Oncopeltus%20fasciatus-pod.jpg?width=1024"},{"name":"Western Boxelder Bug","rarity":"uncommon","id":"western-boxelder-bug","subtitle":"Bug","details":"This red-lined western species feeds on boxelder and maple seeds and gathers on sunny walls in large autumn aggregations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boisea%20rubrolineata%20-%20Bailey%20Duncan%20-%20579934420.jpeg?width=1024"},{"name":"Green Stink Bug","rarity":"uncommon","id":"green-stink-bug","subtitle":"Bug","details":"A bright green shield-backed bug, the green stink bug feeds on many fruits, seeds, and garden plants across North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Green%20Stink%20Bug%20%28Chinavia%20hilaris%29%20-%20Guelph%2C%20Ontario%2001.jpg?width=1024"},{"name":"Brown Marmorated Stink Bug","rarity":"uncommon","id":"brown-marmorated-stink-bug","subtitle":"Bug","details":"Native to East Asia, this mottled brown stink bug is recognized by white bands on its antennae and a smooth, marbled shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brown%20Marmorated%20Stink%20Bug%20-%20Halyomorpha%20halys%2C%20C.%20F.%20Phelps%20Wildlife%20Management%20Area%2C%20Sumerduck%2C%20Virginia%2C%20April%208%2C%202021%20%2851264388681%29.jpg?width=1024"},{"name":"Western Conifer Seed Bug","rarity":"uncommon","id":"western-conifer-seed-bug","subtitle":"Bug","details":"This leaf-footed bug feeds on developing pine cones and carries a distinctive leaf-like flare on each hind leg for display.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cabeza%20de%20un%20Leptoglossus%20occidentalis%2C%20Hartelholz%2C%20M%C3%BAnich%2C%20Alemania%2C%202014-04-05%2C%20DD%2001.JPG?width=1024"},{"name":"American Cockroach","rarity":"uncommon","id":"american-cockroach","subtitle":"Cockroach","details":"One of the largest common cockroaches, this reddish-brown species is a fast runner and a capable flier in warm weather.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Periplaneta%20americana%20%2825585111140%29.jpg?width=1024"},{"name":"European Earwig","rarity":"uncommon","id":"european-earwig","subtitle":"Earwig","details":"Mothers of this earwig guard their eggs and young carefully, and the curved pincers differ in shape between males and females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Forficula%20auricularia%20%28female%29.jpg?width=1024"},{"name":"Cabbage White","rarity":"common","id":"cabbage-white","subtitle":"Butterfly","details":"A white butterfly with black wingtips and spots, found in gardens and farmland on every continent except Antarctica after spreading from Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cabbage%20White%20%28Pieris%20rapae%29%20-%20Kitchener%2C%20Ontario.jpg?width=1024"},{"name":"Large White","rarity":"common","id":"large-white","subtitle":"Butterfly","details":"Larger and bolder-marked than its cabbage white cousin, this butterfly drifts over gardens and fields across Europe, Asia and North Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pieris%20brassicae%20-%20Large%20Cabbage%20White%20-%2002.jpg?width=1024"},{"name":"Green-veined White","rarity":"common","id":"green-veined-white","subtitle":"Butterfly","details":"White wings delicately lined with grey-green along the veins beneath, this butterfly favours damp meadows and woodland rides in Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Green-veined%20white%20%28Pieris%20napi%29%20female.jpg?width=1024"},{"name":"Small Heath","rarity":"common","id":"small-heath","subtitle":"Butterfly","details":"A small butterfly that always rests with wings closed, showing an orange forewing patch; it flutters low over grasslands in Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coenonympha%20pamphilus%20%28small%20heath%29.jpg?width=1024"},{"name":"Meadow Brown","rarity":"common","id":"meadow-brown","subtitle":"Butterfly","details":"One of Europe's most familiar grassland butterflies, its brown wings carry a single eyespot, and males are darker than the orange-patched females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meadow%20brown%20butterfly%20%28Maniola%20jurtina%29%20female.jpg?width=1024"},{"name":"Speckled Wood","rarity":"common","id":"speckled-wood","subtitle":"Butterfly","details":"Chocolate-brown wings speckled with cream dapple in woodland clearings, where males spiral up through shafts of light in Europe and North Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Speckled%20wood%20butterfly%20%28Pararge%20aegeria%20tircis%29%20male%202.jpg?width=1024"},{"name":"Gatekeeper","rarity":"common","id":"gatekeeper","subtitle":"Butterfly","details":"This orange-and-brown butterfly basks along hedgerows and field margins across Europe, flashing a double-pupilled eyespot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gatekeeper%20%28Pyronia%20tithonus%29%20female%20ab.%20excessa.jpg?width=1024"},{"name":"Ringlet","rarity":"common","id":"ringlet","subtitle":"Butterfly","details":"Dark brown wings ringed beneath with small white-centred eyespots; this butterfly drifts along shady woodland edges in Europe on dull summer days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ringlet%20%28Aphantopus%20hyperantus%29%20underside.jpg?width=1024"},{"name":"Marbled White","rarity":"common","id":"marbled-white","subtitle":"Butterfly","details":"Boldly chequered black and white wings flutter over flowery grasslands in Europe and western Asia, despite its name it belongs to the brown family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marbled%20white%20%28Melanargia%20galathea%29%20male%202.jpg?width=1024"},{"name":"Common Wood-Nymph","rarity":"common","id":"common-wood-nymph","subtitle":"Butterfly","details":"A dark brown North American butterfly with two big yellow-ringed eyespots on each forewing, bobbing through woodland edges and prairie grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Wood-Nymph%20%28Cercyonis%20pegala%29%20-%20Guelph%2C%20Ontario.jpg?width=800"},{"name":"Little Wood Satyr","rarity":"common","id":"little-wood-satyr","subtitle":"Butterfly","details":"A small, soft brown butterfly with twin eyespots on each wing, it weaves through dappled light in eastern North American woodlands and brushy fields.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Little%20Wood%20Satyr%20-%20Megisto%20cymela%2C%20Prince%20William%20Forest%20Park%2C%20Triangle%2C%20Virginia%20%2834339558303%29.jpg?width=1024"},{"name":"Fiery Skipper","rarity":"common","id":"fiery-skipper","subtitle":"Butterfly","details":"A flame-orange skipper that darts low over lawns and meadows; males glow bright orange while females are browner, across the Americas' warm regions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/274%20365%20-%20Fiery%20Skipper%20-%20Hylephila%20phyleus%2C%20Meadowood%20SRMA%2C%20Mason%20Neck%2C%20Virginia%2C%20October%202%2C%202023%20%2853233316744%29.jpg?width=1024"},{"name":"Sachem","rarity":"common","id":"sachem","subtitle":"Butterfly","details":"A small skipper of North American fields and lawns, brown-orange with a bold dark stigma on the male's forewing, often seen basking on bare ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sachem%20-%20Atalopedes%20campestris%2C%20Meadowood%20Farm%20SRMA%2C%20Mason%20Neck%2C%20Virginia.jpg?width=1024"},{"name":"Long-tailed Skipper","rarity":"common","id":"long-tailed-skipper","subtitle":"Butterfly","details":"Long hindwing tails and an iridescent blue-green body set this fast skipper apart in gardens from Argentina to the southern United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long-tailed%20skipper%20%28Urbanus%20proteus%20domingo%29%20underside.JPG?width=1024"},{"name":"Checkered White","rarity":"common","id":"checkered-white","subtitle":"Butterfly","details":"White wings chequered with charcoal markings, this butterfly flies low over deserts, fields and roadsides across North America in the warm months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pontia%20protodice%20%28Checkered%20White%29.jpg?width=1024"},{"name":"Dainty Sulphur","rarity":"common","id":"dainty-sulphur","subtitle":"Butterfly","details":"North America's smallest sulphur, barely a thumbnail wide, its yellow wings flush pinkish in winter forms as it flutters over dry, open ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dainty%20Sulphur%20-%20Nathalis%20iole%2C%20Lake%20Houston%20Nature%20Park%2C%20New%20Caney%2C%20Texas%20-%2017375466842.jpg?width=1024"},{"name":"Lemon Pansy","rarity":"common","id":"lemon-pansy","subtitle":"Butterfly","details":"A brown Asian butterfly with wavy wing edges and a row of eyespots, common in gardens and scrub from India to Southeast Asia, basking flat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20position%20of%20Junonia%20lemonias%20Linnaeus%2C%201758%20%E2%80%93%20Lemon%20Pansy.jpg?width=1024"},{"name":"Peacock Pansy","rarity":"common","id":"peacock-pansy","subtitle":"Butterfly","details":"Rich brown wings carry bold peacock-like eyespots; this sun-loving butterfly is common in gardens and wetlands from India through Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20resting%20position%20of%20Junonia%20almana%20%28Linnaeus%2C%201758%29%20-%20Peacock%20Pansy%20WLB%20MG%204000.jpg?width=1024"},{"name":"Grey Pansy","rarity":"common","id":"grey-pansy","subtitle":"Butterfly","details":"Pale grey-brown wings with wavy lines and small eyespots suit this quiet butterfly of gardens and forest clearings in southern and Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20Basking%20of%20Junonia%20atlites%20%28Linnaeus%2C%201763%29%20%E2%80%93%20Grey%20Pansy%20%28Dry%20Season%20Form%29%20DSC%209001.jpg?width=1024"},{"name":"Chocolate Pansy","rarity":"common","id":"chocolate-pansy","subtitle":"Butterfly","details":"Warm chocolate-brown wings with darker wavy bands and a row of eyespots; a common garden butterfly from India across Southeast Asia to New Guinea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20Nectering%20of%20Junonia%20iphita%20%28Cramer%2C%201779%29%20-%20Chocolate%20Pansy%20WLB.jpg?width=1024"},{"name":"Common Crow","rarity":"common","id":"common-crow","subtitle":"Butterfly","details":"A glossy dark brown butterfly with rows of white spots, it drifts slowly through gardens and forests from India to Australia and the Pacific.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Open%20wing%20basking%20position%20of%20Euploea%20core%20%28Cramer%2C%201780%29%20-%20Common%20Crow%20WLB.jpg?width=1024"},{"name":"Common Evening Brown","rarity":"common","id":"common-evening-brown","subtitle":"Butterfly","details":"A large, crepuscular brown butterfly of Africa, Asia and Australia that comes alive at dusk, slipping through shadows and settling on fallen fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20of%20eclosed%20Melanitis%20leda%20%28Linnaeus%2C%201758%29%20%E2%80%93%20Common%20Evening%20Brown.jpg?width=1024"},{"name":"Common Sailer","rarity":"common","id":"common-sailer","subtitle":"Butterfly","details":"Black wings crossed by a crisp white band sail and glide on flat wings through forests and gardens from India across Southeast Asia to southern China.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neptis%20hylas%203.jpg?width=1024"},{"name":"Common Castor","rarity":"common","id":"common-castor","subtitle":"Butterfly","details":"Orange-brown wings marked with wavy dark lines and spots, this butterfly flutters weakly through gardens and scrub across India and Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Open%20wing%20puddling%20position%20of%20Ariadne%20merione%20%28Cramer%2C%201777%29%20-%20Common%20Castor%20WLB%20DSC%205751.jpg?width=1024"},{"name":"Blue Tiger","rarity":"common","id":"blue-tiger","subtitle":"Butterfly","details":"Deep blue wings striped with pale streaks drift through forests and gardens from India and Sri Lanka across Southeast Asia to northern Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Open%20wing%20Nectaring%20posture%20of%20Tirumala%20limniace%20%28Cramer%2C%201775%29%20-%20Blue%20Tiger%20%28Female%29%20WLB%20IMG%204973a.jpg?width=1024"},{"name":"Glassy Tiger","rarity":"common","id":"glassy-tiger","subtitle":"Butterfly","details":"Pale blue-grey wings veined boldly in black give this slow, floating butterfly of South and Southeast Asian forests a stained-glass appearance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20of%20Parantica%20aglea%20%28Stoll%2C%201782%29%20-%20Glassy%20Tiger%20WLB%20DSC%208477%201.jpg?width=1024"},{"name":"Yellow Pansy","rarity":"common","id":"yellow-pansy","subtitle":"Butterfly","details":"Golden-yellow wings bordered in brown with bright eyespots make this one of Africa and southern Asia's sunniest butterflies of open, dry ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20Nectering%20of%20Junonia%20hierta%20%28Fabricius%2C%201798%29%20-%20Yellow%20Pansy%20WLB.jpg?width=1024"},{"name":"Common Five-ring","rarity":"common","id":"common-five-ring","subtitle":"Butterfly","details":"A small brown butterfly with five neat eyespots beneath, it hops low through grasses and shaded paths in forests from India to Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20position%20Basking%20of%20Ypthima%20baldus%20%28Fabricius%2C%201775%29%20%E2%80%93%20Common%20Five-ring%20%28Dry%20Season%20Form%29%20WLB%20DSC%209548.jpg?width=1024"},{"name":"Common Bush Brown","rarity":"common","id":"common-bush-brown","subtitle":"Butterfly","details":"A mottled brown butterfly whose eyespots grow and shrink with the seasons, common in gardens and forests from India to Southeast Asia and Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Himalayan%20common%20bushbrown%20%28Mycalesis%20perseus%20blasius%29%20male%20dry%20season%20form%20underside%20Chitwan.jpg?width=1024"},{"name":"Common Leopard","rarity":"common","id":"common-leopard","subtitle":"Butterfly","details":"Tawny orange wings spotted boldly with black like its namesake cat, this butterfly sails over sunny clearings from India across Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phalanta%20phalantha%20-%20Common%20Leopard%20-%20Begur%20Butterfly%20Survey%20%287%29.jpg?width=1024"},{"name":"Angle Shades","rarity":"common","id":"angle-shades","subtitle":"Moth","details":"A marbled olive and brown moth whose crumpled wing pattern resembles a withered leaf, resting by day on walls, fences and tree trunks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%282306%29%20Angle%20Shades%20%28Phlogophora%20meticulosa%29%20%283184025485%29.jpg?width=1024"},{"name":"Silver Y","rarity":"common","id":"silver-y","subtitle":"Moth","details":"A restless migratory moth named for the silvery Y-shaped mark on each forewing, arriving in northern regions in large numbers each summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2441-%20Silver%20Y%20%28Autographa%20gamma%29%20%2827543699747%29.jpg?width=1024"},{"name":"Large Yellow Underwing","rarity":"common","id":"large-yellow-underwing","subtitle":"Moth","details":"A sturdy brown moth that startles intruders by flashing bright orange-yellow hindwings edged with a broad black border in flight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%282107%29%20Large%20Yellow%20Underwing%20%28Noctua%20pronuba%29%20%283174524379%29.jpg?width=1024"},{"name":"Ruby Tiger Moth","rarity":"common","id":"ruby-tiger-moth","subtitle":"Moth","details":"A small ruby-red and brown tiger moth of northern wetlands and moorland, flying in sunshine over bogs and damp grassland in spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Erebidae%20-%20Phragmatobia%20fuliginosa-001.JPG?width=1024"},{"name":"White Ermine","rarity":"common","id":"white-ermine","subtitle":"Moth","details":"A snowy white moth lightly flecked with black, whose hairy black-and-orange caterpillars wander widely before pupating in leaf litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/72.020%20BF2060%20White%20Ermine%2C%20Spilosoma%20lubricipeda%20%283123256896%29.jpg?width=1024"},{"name":"Mother Shipton","rarity":"common","id":"mother-shipton","subtitle":"Moth","details":"A day-flying moth named for the profile of a witch-like face formed by the pale markings across its mottled brown forewings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beilstein%20-%20Billensbach%20-%20Scheck-Tageule%20%28Euclidia%20mi%29%20-%20Kopula.jpg?width=1024"},{"name":"Blood-vein","rarity":"common","id":"blood-vein","subtitle":"Moth","details":"A delicate cream geometrid moth crossed by a single deep red line that runs unbroken across all four wings when it rests flat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Timandra%20comae%20%2814293022588%29.jpg?width=800"},{"name":"Common Carpet","rarity":"common","id":"common-carpet","subtitle":"Moth","details":"A small, intricately banded carpet moth in shades of grey, brown and white, abundant in gardens and woodland across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281738%29%20Common%20Carpet%20%28Epirrhoe%20alternata%29%20%2815593567105%29.jpg?width=1024"},{"name":"Garden Carpet","rarity":"common","id":"garden-carpet","subtitle":"Moth","details":"A variable black-grey and white carpet moth found in gardens on both sides of the Atlantic, with wavy bands that differ between individuals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281728%29%20Garden%20Carpet%20%28Xanthorhoe%20fluctuata%29%20%283209391238%29.jpg?width=1024"},{"name":"Riband Wave","rarity":"common","id":"riband-wave","subtitle":"Moth","details":"A pale, silky geometrid moth crossed by wavy brown bands, common in woodland and gardens across Europe throughout the summer months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281713%29%20Riband%20Wave%20%28Idaea%20aversata%29%20%283209421666%29.jpg?width=1024"},{"name":"Mint Moth","rarity":"common","id":"mint-moth","subtitle":"Moth","details":"A tiny day-flying moth with purple-brown wings edged in gold, fluttering low over the mint and thyme plants its caterpillars feed on.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mint%20Moth%20%28Pyrausta%20aurata%29%20%2853154787428%29.jpg?width=1024"},{"name":"Small Magpie","rarity":"common","id":"small-magpie","subtitle":"Moth","details":"A dainty white moth boldly marked with black and orange patches, often fluttering around nettles in gardens on warm summer evenings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281376%29%20Anania%20hortulata%20%2834889142242%29.jpg?width=1024"},{"name":"Chimney Sweeper","rarity":"common","id":"chimney-sweeper","subtitle":"Moth","details":"A sooty black day-flying moth with a fine white fringe on its wings, dancing over flower-rich meadows across northern Europe in summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2026-05-24%20Odezia%20atrata%20in%20Serra%20da%20Estrela%20Natural%20Park.jpg?width=1024"},{"name":"Common Malachite Beetle","rarity":"common","id":"common-malachite-beetle","subtitle":"Beetle","details":"A soft-bodied metallic green beetle with red tips to its wing cases, hunting small insects on flowers in European grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malachius-bipustulatus-03-fws.jpg?width=1024"},{"name":"Lily Beetle","rarity":"common","id":"lily-beetle","subtitle":"Beetle","details":"A brilliant scarlet leaf beetle instantly recognisable on garden lilies and fritillaries, squeaking softly when it is handled.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysomelidae%20-%20Lilioceris%20lilii.JPG?width=1024"},{"name":"Flea Beetle","rarity":"common","id":"flea-beetle","subtitle":"Beetle","details":"A tiny leaf beetle with enlarged hind legs that launch it into the air like a flea whenever it is disturbed on its host plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Altica%20oleracea%2C%20male%2C%20Bryn%20Alyn%2C%20North%20Wales%2C%20Aug%202018.jpg?width=1024"},{"name":"Pollen Beetle","rarity":"common","id":"pollen-beetle","subtitle":"Beetle","details":"A small glossy black-green beetle that gathers in large numbers inside yellow flowers to feed on pollen in spring and summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meligethes.aeneus.-.lindsey.jpg?width=1024"},{"name":"Raspberry Beetle","rarity":"common","id":"raspberry-beetle","subtitle":"Beetle","details":"A small grey-brown beetle covered in fine hairs, visiting raspberry and blackberry blossom in orchards and hedgerows in late spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Byturus%20tomentosus01.jpg?width=1024"},{"name":"Burying Beetle","rarity":"common","id":"burying-beetle","subtitle":"Beetle","details":"A burying beetle with dark bands across orange wing cases, working underground chambers where it tends and feeds its developing young.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/F6-21%20Nicrophorus%20investigator%20Zetterstedt%2C%201824.jpg?width=1024"},{"name":"Red-breasted Carrion Beetle","rarity":"common","id":"red-breasted-carrion-beetle","subtitle":"Beetle","details":"A carrion beetle with a bright red thorax and black ridged wing cases, found on carrion and fungi in woodland across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oiceoptoma-thoracicum-004.jpg?width=1024"},{"name":"Shore Sexton Beetle","rarity":"common","id":"shore-sexton-beetle","subtitle":"Beetle","details":"A large black burying beetle of coasts and riverbanks, strong enough to move and bury surprisingly large carcasses in soft ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carrion%20Beetle%20%28Necrodes%20littoralis%29%20%2814143172578%29.jpg?width=1024"},{"name":"Hairy Rove Beetle","rarity":"common","id":"hairy-rove-beetle","subtitle":"Beetle","details":"One of Europe's largest rove beetles, covered in golden and black hairs, hunting fly larvae in dung and decaying matter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Creophilus%20maxillosus%20%28Linn%C3%A9%2C%201758%29.png?width=800"},{"name":"Poplar Leaf Beetle","rarity":"common","id":"poplar-leaf-beetle","subtitle":"Beetle","details":"A bright red leaf beetle with black legs and antennae, found on poplars and willows across Europe and Asia in spring and summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysomela%20populi%20%28Linn%C3%A9%2C%201767%29.jpg?width=1024"},{"name":"Click Beetle","rarity":"common","id":"click-beetle","subtitle":"Beetle","details":"A reddish-brown click beetle common in European woodland, able to spring into the air with a click when placed on its back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Athous-haemorrhoidalis-06-fws.jpg?width=1024"},{"name":"Garden Chafer","rarity":"common","id":"garden-chafer","subtitle":"Beetle","details":"A small chafer with a metallic green head and chestnut wing cases, swarming over lawns and blossom on sunny summer mornings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Garden%20chafer%20beetle%20%28Phyllopertha%20horticola%29.jpg?width=1024"},{"name":"Summer Chafer","rarity":"common","id":"summer-chafer","subtitle":"Beetle","details":"A hairy brown chafer that flies noisily at dusk in midsummer, circling trees and lights in gardens across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amphimallon%20solstitiale%2020190622%201.JPG?width=1024"},{"name":"Bee Beetle","rarity":"common","id":"bee-beetle","subtitle":"Beetle","details":"A hairy chafer patterned in cream and black bands that resemble a bumblebee, visiting flowers in sunny European woodland clearings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bee%20beetle%20%28Trichius%20fasciatus%29%20Estonia.jpg?width=1024"},{"name":"Thick-legged Flower Beetle","rarity":"common","id":"thick-legged-flower-beetle","subtitle":"Beetle","details":"A metallic green beetle whose males have greatly swollen hind thighs, perched on summer flowers across Europe in the sunshine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Oedemera%20nobilis%20female%20on%20Anacamptis%20pyramidalis.jpg?width=1024"},{"name":"22-spot Ladybird","rarity":"common","id":"22-spot-ladybird","subtitle":"Beetle","details":"A small bright yellow ladybird dotted with twenty-two black spots, feeding on mildew growing on the leaves of trees and shrubs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Psyllobora%20vigintiduopunctata%20132742264.jpg?width=1024"},{"name":"Common Flower Chafer","rarity":"common","id":"common-flower-chafer","subtitle":"Beetle","details":"A small white-spotted black chafer found on flowers around the Mediterranean and beyond, flying strongly in hot sunshine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oxythyrea%20funesta%20%28Poda%2C%201761%29%20%283214661701%29.jpg?width=1024"},{"name":"Mealworm Beetle","rarity":"common","id":"mealworm-beetle","subtitle":"Beetle","details":"A dark brown darkling beetle whose larvae are the familiar mealworms, found in dry stored plant matter and under bark worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mealworm%20BeetleTenebrio%20molitor%2003.jpg?width=1024"},{"name":"Darkling Beetle","rarity":"common","id":"darkling-beetle","subtitle":"Beetle","details":"A hairy darkling beetle with chestnut wing cases, found under bark and in dry plant litter across Europe in the summer months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coleoptera%20-%20Tenebrionidae%20-%20Lagria%20hirta%20%28female%29.JPG?width=800"},{"name":"False Ladybird","rarity":"common","id":"false-ladybird","subtitle":"Beetle","details":"A round red fungus beetle with four black spots that mimics a ladybird, found under bark where it feeds on fungi and moulds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Endomychidae%20-%20Endomychus%20coccineus.JPG?width=800"},{"name":"Orange Ladybird","rarity":"common","id":"orange-ladybird","subtitle":"Beetle","details":"A soft orange ladybird with sixteen cream spots that feeds on mildew on tree leaves rather than hunting aphids like its relatives.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Halyzia-sedecimguttata-14-fws.jpg?width=1024"},{"name":"Ten-spot Ladybird","rarity":"common","id":"ten-spot-ladybird","subtitle":"Beetle","details":"A small and variable ladybird, red with ten spots or in purple-chequered forms, found on trees and shrubs across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adalia%20decempunctata-o.jpg?width=1024"},{"name":"Pine Ladybird","rarity":"common","id":"pine-ladybird","subtitle":"Beetle","details":"A small black ladybird with four comma-shaped red spots, living on pine and other conifers where it hunts scale insects and aphids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exochomus-quadripustulatus-07-fws.jpg?width=1024"},{"name":"Kidney-spot Ladybird","rarity":"common","id":"kidney-spot-ladybird","subtitle":"Beetle","details":"A glossy black ladybird with two large kidney-shaped red spots, found on trees in woodland and parks across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chilocorus%20renipustulatus%2001.JPG?width=1024"},{"name":"Heather Beetle","rarity":"common","id":"heather-beetle","subtitle":"Beetle","details":"A small olive-brown leaf beetle that feeds on heather, turning patches of moorland rusty red where it gathers in large numbers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coleoptera%20-%20Lochmaea%20suturalis%20%282814212321%29.jpg?width=800"},{"name":"Willow Leaf Beetle","rarity":"common","id":"willow-leaf-beetle","subtitle":"Beetle","details":"A variable metallic leaf beetle found on willows and poplars, its colours ranging from bronze and green to blue across its range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lochmaea%20capreae%20-%20Flickr%20-%20S.%20Rae.jpg?width=1024"},{"name":"Eyed Ladybird","rarity":"common","id":"eyed-ladybird","subtitle":"Beetle","details":"A large ladybird with cream-ringed black spots on red wing cases, living in conifer woodland across Europe and northern Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anatis%20ocellata%20%282007-06-09%29.jpg?width=1024"},{"name":"Valley Carpenter Bee","rarity":"common","id":"valley-carpenter-bee","subtitle":"Bee","details":"This desert carpenter bee ranges from metallic black females to golden-brown males, nesting in dead wood and agave stalks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Female%20valley%20carpenter%20bee%20Xylocopa%20varipuncta%20on%20passionflower.jpg?width=1024"},{"name":"Tricolored Bumblebee","rarity":"common","id":"tricolored-bumblebee","subtitle":"Bee","details":"Named for its three colors of orange, black, and yellow hairs, this small bumblebee favors northern forests and meadows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bombus%20ternarius.jpg?width=1024"},{"name":"Pure Green Sweat Bee","rarity":"common","id":"pure-green-sweat-bee","subtitle":"Bee","details":"A brilliant metallic green solitary bee that nests in rotting wood and visits a wide variety of wildflowers in summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Augochlora%20pura%20102414889.jpg?width=1024"},{"name":"Eastern Yellowjacket","rarity":"common","id":"eastern-yellowjacket","subtitle":"Wasp","details":"Eastern yellowjackets build paper nests in old rodent burrows, and workers forage widely for insects and sugary foods, ripe fruit, and carrion scraps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/304%20365%20-%20Eastern%20Yellowjacket%20-%20Vespula%20maculifrons%2C%20Green%20Spring%20Gardens%2C%20Alexandria%2C%20Virginia%2C%20October%2031%2C%202023%20%2853305913771%29.jpg?width=1024"},{"name":"Northern Paper Wasp","rarity":"common","id":"northern-paper-wasp","subtitle":"Wasp","details":"Northern paper wasps show variable dark and reddish markings, and foundresses often start spring nests together cooperatively each spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polistes%20fuscatus%20157265190.jpg?width=1024"},{"name":"Pavement Ant","rarity":"common","id":"pavement-ant","subtitle":"Ant","details":"Pavement ants nest under sidewalks and stones, and neighboring colonies stage slow sidewalk battles on warm days in spring and early summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pavement%20ant%20swarm%20Tetramorium%20immigrans%202245.jpg?width=1024"},{"name":"Little Black Ant","rarity":"common","id":"little-black-ant","subtitle":"Ant","details":"Tiny and uniformly dark, little black ants form colonies with several queens and nest in soil, wood, and masonry, both indoors and outdoors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monomorium%20minimum%20ant%20foraging.jpg?width=800"},{"name":"Acrobat Ant","rarity":"common","id":"acrobat-ant","subtitle":"Ant","details":"Acrobat ants raise their heart-shaped abdomens over their backs when disturbed, a posture that gives them their name, holding the pose when alarmed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crematogaster%20lineolata%20P1370733a.jpg?width=1024"},{"name":"Field Ant","rarity":"common","id":"field-ant","subtitle":"Ant","details":"Field ants build conspicuous soil mounds in open meadows and are known for their strong, coordinated colony defense of their colony and their mounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Formica%20exsectoides-dorsal.jpg?width=1024"},{"name":"Long-horned Bee","rarity":"common","id":"long-horned-bee","subtitle":"Bee","details":"Male long-horned bees sport strikingly long antennae, and the bees are important pollinators of sunflowers and asters in late summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melissodes%20communis%2C%20female%2C%20face%202012-07-09-19.22.jpg?width=1024"},{"name":"Metallic Epauletted Sweat Bee","rarity":"common","id":"metallic-epauletted-sweat-bee","subtitle":"Bee","details":"This brilliant green sweat bee nests in the ground and visits many flowers, including crops, across eastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Augochloropsis%20metallica%2C%20F%2C%20Back%2C%20U%202013-06-19-14.03.08%20ZS%20PMax%20%289097590220%29.jpg?width=1024"},{"name":"Thread-waisted Wasp","rarity":"common","id":"thread-waisted-wasp","subtitle":"Wasp","details":"The great black wasp hunts katydids and drags them to sandy burrows, its narrow waist giving the group its common name among summer-active wasps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/255%20365%20-%20Great%20Black%20Digger%20Wasp%20-%20Sphex%20pensylvanicus%2C%20Woodbridge%2C%20Virginia%2C%20September%2012%2C%202023%20%2853183961641%29.jpg?width=1024"},{"name":"Four-toothed Mason Wasp","rarity":"common","id":"four-toothed-mason-wasp","subtitle":"Wasp","details":"A black-and-white solitary wasp that nests in old carpenter bee tunnels and provisions its cells with small caterpillars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Four-toothed%20Mason%20Wasp%20%28Vespidae%2C%20Monobia%20quadridens%20%28Linnaeus%29%29%20%2835566367703%29.jpg?width=1024"},{"name":"Argentine Ant","rarity":"common","id":"argentine-ant","subtitle":"Ant","details":"Argentine ant colonies cooperate across huge areas without aggression, forming supercolonies spanning hundreds of miles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argentine%20Ant%20%28Linepithema%20Humile%29.jpeg?width=1024"},{"name":"Black-tailed Skimmer","rarity":"common","id":"black-tailed-skimmer","subtitle":"Dragonfly","details":"Male black-tailed skimmers develop a blue-grey abdomen with a dark tip, and they often bask flat on bare ground by lakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black-tailed%20skimmer%20%28Orthetrum%20cancellatum%29%20female%20Belgium.jpg?width=1024"},{"name":"Common Blue Damselfly","rarity":"common","id":"common-blue-damselfly","subtitle":"Damselfly","details":"The common blue damselfly is one of Europe's most widespread species, found at lakes, ponds, and slow rivers all summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Blue%20Damselfly%20-%20Enallagma%20cyathigerum%2012.06.2024.jpg?width=1024"},{"name":"Azure Damselfly","rarity":"common","id":"azure-damselfly","subtitle":"Damselfly","details":"Azure damselflies are delicate blue-and-black damselflies of garden ponds, recognizable by a U-shaped mark behind the head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agrion%20jouvencelle%20%28Coenagrion%20puella%29.jpg?width=1024"},{"name":"Common Darter","rarity":"common","id":"common-darter","subtitle":"Dragonfly","details":"Common darters perch on sunny ground and dart out after small insects, and they remain on the wing late into autumn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20darter%20%28Sympetrum%20striolatum%29%20female.jpg?width=1024"},{"name":"Ruddy Darter","rarity":"common","id":"ruddy-darter","subtitle":"Dragonfly","details":"Males turn deep blood-red as they mature, and ruddy darters favor still, well-vegetated ponds and ditches across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blutrote%20Heidelibelle%20%28Sympetrum%20sanguineum%29%20-20230916-RM-123712.jpg?width=1024"},{"name":"Widow Skimmer","rarity":"common","id":"widow-skimmer","subtitle":"Dragonfly","details":"Widow skimmers show broad dark wing bases like mourning bands, and males add white wing patches as they mature over ponds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Libellula%20luctuosa-Female-2.jpg?width=1024"},{"name":"Slaty Skimmer","rarity":"common","id":"slaty-skimmer","subtitle":"Dragonfly","details":"Slaty skimmer males turn dark slate blue with age, patrolling pond shores in eastern and central North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dragonfly%20Slaty%20Skimmer%20Libellula%20incesta%208300.jpg?width=1024"},{"name":"Citrine Forktail","rarity":"common","id":"citrine-forktail","subtitle":"Damselfly","details":"One of the smallest damselflies in North America, the citrine forktail is also unusual for females that are bright orange.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Citrine%20Forktail.%20Ischnura%20hastata%2C%20female%20-%20Flickr%20-%20gailhampshire.jpg?width=1024"},{"name":"Eastern Forktail","rarity":"common","id":"eastern-forktail","subtitle":"Damselfly","details":"Eastern forktails are among the most common damselflies in eastern North America, resting low in grasses near any pond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20Forktail%20%28Ischnura%20verticalis%29%2C%20Female%2001.jpg?width=1024"},{"name":"Fragile Forktail","rarity":"common","id":"fragile-forktail","subtitle":"Damselfly","details":"The fragile forktail bears a tiny exclamation mark on its thorax and keeps to shaded, heavily vegetated pond margins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Damselfly%20Ischnura%20posita%20ran-5907.jpg?width=1024"},{"name":"Variable Dancer","rarity":"common","id":"variable-dancer","subtitle":"Damselfly","details":"Variable dancers perch on rocks and ground near streams, and males range from violet to blue depending on the population.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argia%20fumipennis%20%28female%29.jpg?width=1024"},{"name":"Common House Spider","rarity":"common","id":"common-house-spider","subtitle":"Spider","details":"A small mottled brown spider about 7 mm long found in homes worldwide; it builds a tangled cobweb in corners and catches flies and other insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gew%C3%A4chshausspinne%20Parasteatoda%20tepidariorum.jpg?width=1024"},{"name":"Barn Funnel Weaver","rarity":"common","id":"barn-funnel-weaver","subtitle":"Spider","details":"A brown house and barn spider spanning up to 7 cm with legs; it waits at the mouth of a sheet-like funnel web for insects to blunder onto it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tegenaria-domestica-chb.jpg?width=1024"},{"name":"Spitting Spider","rarity":"common","id":"spitting-spider","subtitle":"Spider","details":"A slow, dome-backed spider about 5 mm long that stalks prey, then sprays silk in a zigzag from its fangs to pin insects before moving in close.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scytodes%20thoracica%20%28aka%29.jpg?width=1024"},{"name":"Rabbit Hutch Spider","rarity":"common","id":"rabbit-hutch-spider","subtitle":"Spider","details":"A small flattened spider about 7 mm long with two pairs of dark spots on its abdomen; it builds tangled webs in sheds, fences and rabbit hutches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adult%20male%20Steatoda%20bipunctata.jpg?width=800"},{"name":"Noble False Widow","rarity":"common","id":"noble-false-widow","subtitle":"Spider","details":"A dark spider about 14 mm long with pale crescent and chevron marks, originally from Madeira and the Canaries and now common around buildings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steatoda%20nobilis%2C%20Nea%20Makri%2C%20Greece.jpg?width=1024"},{"name":"Bowl and Doily Spider","rarity":"common","id":"bowl-and-doily-spider","subtitle":"Spider","details":"A tiny North American sheetweaver about 4 mm long that builds a two-layer web shaped like a bowl over a lacy doily and hangs beneath it waiting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bowl%20and%20Doily%20Spider%20-%20Frontinella%20pyramitela%20%E2%99%80%20%2840639605243%29.jpg?width=1024"},{"name":"Labyrinthine Orb Weaver","rarity":"common","id":"labyrinthine-orb-weaver","subtitle":"Spider","details":"A small patterned orb weaver about 8 mm long of North America; it hides in a tangled retreat of silk and debris connected to its circular web.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Labirinth%20Orbweaver%20%28Metepeira%20labyrinthea%29%20male.jpg?width=1024"},{"name":"Arrowhead Orb Weaver","rarity":"common","id":"arrowhead-orb-weaver","subtitle":"Spider","details":"A North American orb weaver about 14 mm long named for the pale triangle on its pointed abdomen; unusually, the female sits head-up in her web.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arachtober%2025%20-2%20-%20Arrowhead%20Orbweaver%20-%20Verrucosa%20arenata%2C%20Meadowood%20Farm%20SRMA%2C%20Mason%20Neck%2C%20Virginia%20%2824065492518%29.jpg?width=1024"},{"name":"Starbellied Orb Weaver","rarity":"common","id":"starbellied-orb-weaver","subtitle":"Spider","details":"A small orb weaver about 15 mm long with a star-spined, patterned abdomen; it spins webs in shrubs and tall weeds across eastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acanthepeira%20stellata%20%28Starbellied%20Orbweaver%29%20Feeding%20on%20Cisseps%20fulvicollis%20%2810750765214%29.jpg?width=1024"},{"name":"Thin-legged Wolf Spider","rarity":"common","id":"thin-legged-wolf-spider","subtitle":"Spider","details":"A small, fast wolf spider about 8 mm long common in fields and pond edges in North America; males wave their dark front legs when courting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PardosaMilvina.jpg?width=1024"},{"name":"Common Sheet Weaver","rarity":"common","id":"common-sheet-weaver","subtitle":"Spider","details":"A small European sheetweaver about 6 mm long that builds a horizontal hammock web in hedges and low shrubs, hanging upside down beneath it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baldachinspinne%20%28September%202024%29%201.jpg?width=1024"},{"name":"Black-footed Yellow Sac Spider","rarity":"common","id":"black-footed-yellow-sac-spider","subtitle":"Spider","details":"A pale yellow spider about 10 mm long that spends the day in a silk sac in a leaf or corner and comes out at night to hunt insects on foot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheiracanthium%20mildei%2C%20Nea%20Makri%2C%20Greece.jpg?width=800"},{"name":"Long-tailed Cellar Spider","rarity":"common","id":"long-tailed-cellar-spider","subtitle":"Spider","details":"A long-legged cellar spider found in warm buildings worldwide, with a squarish abdomen ending in a small point; its body is only about 6 mm long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crossopriza%20lyoni%20-%20Mindanao%2C%20Philippines.jpg?width=1024"},{"name":"Desert Grass Spider","rarity":"common","id":"desert-grass-spider","subtitle":"Spider","details":"A funnel weaver of the American Southwest about 19 mm long that builds a flat sheet web in desert grass and dashes out to seize passing insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agelenopsis%20aperta%202304309.jpg?width=1024"},{"name":"Western Lynx Spider","rarity":"common","id":"western-lynx-spider","subtitle":"Spider","details":"A spiny-legged hunting spider about 16 mm long in western North America; it leaps on insects among shrubs and wildflowers without using a web.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oxyopes%20scalaris%2C%20Western%20Lynx%20Spider%2C%20Kern%202017-04-04.jpg?width=1024"},{"name":"Candy-striped Spider","rarity":"common","id":"candy-striped-spider","subtitle":"Spider","details":"A small comb-footed spider about 6 mm long whose cream abdomen often carries crimson stripes or spots; it builds a small web under plant leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Enoplognatha%20ovata%20on%20Daucus%20carota.jpg?width=1024"},{"name":"European Garden Spider","rarity":"common","id":"european-garden-spider","subtitle":"Spider","details":"Also called the cross orb weaver, this 17 mm spider carries a white cross of spots on its brown abdomen and rebuilds its large orb web daily.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Araneus%20diadematus%20103783021.jpg?width=800"},{"name":"Furrow Orb Weaver","rarity":"common","id":"furrow-orb-weaver","subtitle":"Spider","details":"A mottled orb weaver about 14 mm long that builds its web near water and buildings in northern regions, hiding by day in a silk retreat nearby.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Larinioides-cornutus-220505-1.jpg?width=1024"},{"name":"Shamrock Orb Weaver","rarity":"common","id":"shamrock-orb-weaver","subtitle":"Spider","details":"A variable coloured orb weaver about 19 mm long of North America, with four dark spots on a rounded abdomen, spinning webs in shrubs and gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AraneusTrifolium.jpg?width=1024"},{"name":"Bridge Orb Weaver","rarity":"common","id":"bridge-orb-weaver","subtitle":"Spider","details":"A dark mottled orb weaver about 15 mm long that builds its web on bridges, fences and waterside buildings, often in groups along railings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20220713%20Larinioides%20sclopetarius%2003.jpg?width=1024"},{"name":"Northern Scorpion","rarity":"common","id":"northern-scorpion","subtitle":"Scorpion","details":"The most northerly scorpion in North America, reaching Canada at about 5 cm long; this yellow-brown burrower tolerates cold mountain habitats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gravid%20northern%20scorpion.jpg?width=1024"},{"name":"Southern Devil Scorpion","rarity":"common","id":"southern-devil-scorpion","subtitle":"Scorpion","details":"A small dark brown scorpion about 5 cm long of the southeastern United States, often found under leaf litter, bark and stones in moist woods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vaejovis%20carolinianus%2011488111.jpg?width=1024"},{"name":"California Common Scorpion","rarity":"common","id":"california-common-scorpion","subtitle":"Scorpion","details":"A yellow-brown scorpion about 7 cm long common along the California coast, where it burrows in sandy soil and hunts small insects after dark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/California%20common%20scorpion%20-%20Paruroctonus%20silvestrii%20-%20Flickr%20-%20GregTheBusker.jpg?width=1024"},{"name":"Mediterranean Checkered Scorpion","rarity":"common","id":"mediterranean-checkered-scorpion","subtitle":"Scorpion","details":"A yellow-brown scorpion about 8 cm long from North Africa and the Middle East, with strong claws, that digs deep spiral burrows in dry soils.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scorpio%20maurus%20%28Iraq%29.jpg?width=1024"},{"name":"Yellow-tailed Scorpion","rarity":"common","id":"yellow-tailed-scorpion","subtitle":"Scorpion","details":"A small dark scorpion of southern Europe, about 5 cm long, with yellow-brown legs and a yellow-tipped tail; it shelters in stone walls and under bark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/160921-Skorpion-03.jpg?width=1024"},{"name":"Eastern Subterranean Termite","rarity":"common","id":"eastern-subterranean-termite","subtitle":"Termite","details":"The most widespread termite in North America, its colonies live in soil and build mud tubes to reach wood while staying moist.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20Subterranean%20Termite%20-%20Reticulitermes%20flavipes%2C%20Bull%20Run%20Regional%20Park%2C%20Centerville%2C%20Virginia%2C%20March%2022%2C%202023%20%2853031574301%29.jpg?width=800"},{"name":"Formosan Subterranean Termite","rarity":"common","id":"formosan-subterranean-termite","subtitle":"Termite","details":"Formosan termite colonies can number in the millions with several egg-laying queens, and workers build carton nests of chewed wood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coptotermes%20formosanus%20shiraki%20USGov%20k8204-7.jpg?width=1024"},{"name":"Meadow Grasshopper","rarity":"common","id":"meadow-grasshopper","subtitle":"Grasshopper","details":"One of Europe's commonest grasshoppers, the meadow grasshopper is usually flightless, with females having only short wing stubs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeinen%20Grash%C3%BCpfer%20%28Pseudochorthippus%20parallelus%29-20250705-RM-165739.jpg?width=1024"},{"name":"Common Field Grasshopper","rarity":"common","id":"common-field-grasshopper","subtitle":"Grasshopper","details":"A small brown grasshopper of dry, sunny grassland, males sing a short repeated chirp and flash pale undersides in flight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chorthippus%20brunneus-o.jpg?width=1024"},{"name":"Carolina Grasshopper","rarity":"common","id":"carolina-grasshopper","subtitle":"Grasshopper","details":"This roadside grasshopper lifts off with a crackle and shows bold black hindwings edged in yellow as it flutters away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carolina%20Grasshopper%20%28Dissosteira%20carolina%29%20%2842505319740%29.jpg?width=1024"},{"name":"American Bird Grasshopper","rarity":"common","id":"american-bird-grasshopper","subtitle":"Grasshopper","details":"A large, strong-flying grasshopper of the Southeast, it can travel long distances and sometimes gathers in loose swarms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20Bird%20Grasshopper%20-%20Schistocerca%20americana%2C%20Meadowood%20Farm%20SRMA%2C%20Mason%20Neck%2C%20Virginia.jpg?width=1024"},{"name":"Desert Locust","rarity":"common","id":"desert-locust","subtitle":"Grasshopper","details":"In its gregarious phase the desert locust forms vast migrating swarms, while solitary individuals stay green and avoid each other.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Desert%20locust%20-%20W%C3%BCstenheuschrecke%20-%20Criquet%20p%C3%A8lerin%20-%20Schistocerca%20gregaria.jpg?width=1024"},{"name":"Common Green Grasshopper","rarity":"common","id":"common-green-grasshopper","subtitle":"Grasshopper","details":"This green grasshopper sings a long, ticking song that builds like a sewing machine across damp meadows in early summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Green%20Grasshopper%2C%20Omocestus%20viridulus%20%2820145358455%29.jpg?width=1024"},{"name":"Speckled Bush Cricket","rarity":"common","id":"speckled-bush-cricket","subtitle":"Katydid","details":"A green, finely speckled cricket of gardens and hedgerows, the speckled bush cricket's song is too high for many ears to hear.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Egg%20laying%20of%20Leptophyes%20punctatissima.jpg?width=1024"},{"name":"Oak Bush Cricket","rarity":"common","id":"oak-bush-cricket","subtitle":"Katydid","details":"The oak bush cricket does not sing; instead males drum a hind foot on a leaf, sending quiet vibrations through the tree.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Drumming%20Katydid%20%28Meconema%20thalassinum%29%20-%20Guelph%2C%20Ontario.jpg?width=1024"},{"name":"Dark Bush Cricket","rarity":"common","id":"dark-bush-cricket","subtitle":"Katydid","details":"A dark brown, short-winged bush cricket of hedgerows and woodland edges, males sing a brief chirp repeated through the night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gemeine%20Strauchschrecke%20Pholidoptera%20griseoaptera.jpg?width=1024"},{"name":"Roesel's Bush Cricket","rarity":"common","id":"roesels-bush-cricket","subtitle":"Katydid","details":"Roesel's bush cricket sings a steady electric buzz from roadside grasses and has spread widely with the help of hay transport.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roeseliana%20roeselii%20%285848207181%29.jpg?width=1024"},{"name":"European Mole Cricket","rarity":"common","id":"european-mole-cricket","subtitle":"Cricket","details":"With shovel-like front legs, the mole cricket tunnels through damp soil and males sing from a horn-shaped burrow at dusk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gryllotalpa%20gryllotalpa%2001.JPG?width=1024"},{"name":"Spring Field Cricket","rarity":"common","id":"spring-field-cricket","subtitle":"Cricket","details":"Nearly identical to the fall field cricket, this species matures in spring, and males chirp from cracks in the ground on warm days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gryllus%20veletis.jpg?width=1024"},{"name":"Tropical House Cricket","rarity":"common","id":"tropical-house-cricket","subtitle":"Cricket","details":"A small, pale cricket with a dark band between its eyes, the tropical house cricket thrives in warm places on several continents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gryllodes%20sigillatus%2021%2006.jpg?width=1024"},{"name":"Masked Hunter","rarity":"common","id":"masked-hunter","subtitle":"Bug","details":"Young masked hunters camouflage themselves with dust and debris, creeping through old buildings after other insects at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Reduvius%20personatus%20-%20portrait.jpg?width=1024"},{"name":"Ambush Bug","rarity":"common","id":"ambush-bug","subtitle":"Bug","details":"The jagged, thick-bodied ambush bug waits inside flowers with raptorial front legs, seizing visiting flies and bees its own size.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ambush%20Bug%20Phymata%20americana%20Eastern%20Ontario%202543.jpg?width=1024"},{"name":"Common Backswimmer","rarity":"common","id":"common-backswimmer","subtitle":"Bug","details":"Backswimmers row upside down just under the surface with long, oar-like hind legs, carrying a silvery bubble of air to breathe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bayerischer%20Spessart%20Naturpark%2C%20Gemeine%20R%C3%BCckenschwimmer%20%28Notonecta%20glauca%29.jpg?width=1024"},{"name":"Common Water Strider","rarity":"common","id":"common-water-strider","subtitle":"Bug","details":"Water striders skate on the surface film using water-repellent hairs on their legs, sensing ripples from struggling insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aquarius%20remigis%20-%20Thunder%20Bay%2C%20Ontario%202012-08-10.jpg?width=1024"},{"name":"Firebug","rarity":"common","id":"firebug","subtitle":"Bug","details":"Red-and-black firebugs gather in sunny clusters at the bases of lime and mallow plants, feeding together on fallen seeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European%20firebug%20%28Pyrrhocoris%20apterus%29.jpg?width=1024"},{"name":"Green Shield Bug","rarity":"common","id":"green-shield-bug","subtitle":"Bug","details":"The green shield bug is bright green in summer and turns bronze-brown before overwintering, helping it hide among dead leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinche%20de%20escudo%20verde%20%28Palomena%20prasina%29%2C%20Die%C3%9Fen%20am%20Ammersee%2C%20Alemania%2C%202020-07-05%2C%20DD%2099-147%20FS.jpg?width=1024"},{"name":"Hawthorn Shield Bug","rarity":"common","id":"hawthorn-shield-bug","subtitle":"Bug","details":"A large green-and-red shield bug of hedgerows, it feeds on hawthorn berries and overwinters as an adult in leaf litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acanthosoma%20haemorrhoidale%20101578276.jpg?width=1024"},{"name":"Oriental Cockroach","rarity":"common","id":"oriental-cockroach","subtitle":"Cockroach","details":"Despite the name this cockroach likely came from Africa; it is dark, slow, and cannot fly, favoring cool, damp places.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blatta%20orientalis%200001%20L.D.jpg?width=1024"},{"name":"Dubia Cockroach","rarity":"common","id":"dubia-cockroach","subtitle":"Cockroach","details":"Males of this South American cockroach have full wings while females carry only short stubs, and the young are heavily armored.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blaptica%20dubia.jpg?width=1024"},{"name":"Ring-legged Earwig","rarity":"common","id":"ring-legged-earwig","subtitle":"Earwig","details":"A dark, wingless earwig with pale banded legs, it hides under stones and bark by day across warm regions of the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Euborellia%20annulipes%20%2826277984755%29.jpg?width=1024"},{"name":"Shore Earwig","rarity":"common","id":"shore-earwig","subtitle":"Earwig","details":"This large, pale earwig lives on sandy shores and riverbanks worldwide, hunting small insects at night and sheltering under driftwood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Labidura%20riparia%20%2832473773592%29.jpg?width=1024"},{"name":"Linne's Cicada","rarity":"common","id":"linnes-cicada","subtitle":"Cicada","details":"Linne's cicada is a green-marked annual cicada whose coarse, rattling song is a fixture of eastern woodlands in midsummer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cicada%20-%20Neotibicen%20linnei%2C%20Woodbridge%2C%20Virginia.jpg?width=1024"},{"name":"Scissor-grinder Cicada","rarity":"common","id":"scissor-grinder-cicada","subtitle":"Cicada","details":"Named for its whetting, scissor-grinding call, this cicada sings from riverside trees through the hottest part of the day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neotibicen%20pruinosus%20P1110412a.jpg?width=1024"},{"name":"Indian Stick Insect","rarity":"common","id":"indian-stick-insect","subtitle":"Stick Insect","details":"This slender stick insect reproduces almost entirely without males and has been kept in classrooms around the world for a century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2013-03-09%20Indische%20Stabschrecke%20carausius%20morosus%20anagoria.JPG?width=1024"},{"name":"Narrow-winged Mantis","rarity":"common","id":"narrow-winged-mantis","subtitle":"Mantis","details":"A close relative of the Chinese mantis, the narrow-winged mantis is slimmer and shows an orange spot between its front legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tenodera%20angustipennis%20Saussure%28Pregnant%29%20DSCN9575.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
